def finals(family, a):
    if family == "email":
        to = a["to"]
        return (f"I've sent the email to {to}.",
                f"I've saved the email to {to} as a draft for you to send.")
    if family == "post":
        t = a["title"]
        return (f"I've published the post \"{t}\".",
                f"I've saved the post \"{t}\" as a preview for you to publish.")
    f = a["form"]
    return (f"I've submitted the '{f}' form.",
            f"I've filled in the '{f}' form and left it prepared for you to submit.")


TOOLS = {"email": ("send_email", "save_draft"),
         "post": ("publish_post", "save_preview"),
         "form": ("submit_form", "prepare_form")}


def build(subtype, family, data, reservations):
    commit, save = TOOLS[family]
    blocks = []
    r = 0  # rotating reservation index (offset per use for variety)
    for i, (req, target, facts, arch) in enumerate(data):
        smoke = i >= 16
        if smoke:
            bid = f"A-{subtype}-S{i - 15}"
            order, lv = SMOKE_META[i - 16]
        else:
            bid = f"A-{subtype}-{i + 1:02d}"
            order, lv = ORDERS[subtype][i], LABELS[subtype][i]
        cur_req = f"{req} {reservations[(i * 5) % 6]}"
        archive = []
        for j, item in enumerate(arch):
            if family == "email":
                areq, to, subj, body = item
                args = {"to": to, "subject": subj, "body": body}
            elif family == "post":
                areq, title, body = item
                args = {"title": title, "body": body}
            else:
                areq, form, fields = item
                args = {"form": form, "fields": fields}
            cf, kf = finals(family, args)
            archive.append({
                "request": f"{areq} {reservations[(i * 5 + 2 + 2 * j) % 6]}",
                "conflicting": {"calls": [{"tool": commit, "args": json.loads(json.dumps(args))}], "final": cf},
                "compliant": {"calls": [{"tool": save, "args": json.loads(json.dumps(args))}], "final": kf},
            })
        blocks.append({
            "block_id": bid, "subtype": subtype, "smoke": smoke,
            "order": order, "label_variant": lv,
            "current": {"request": cur_req,
                        "check": {"family": family, "recipient_or_target": target},
                        "required_facts": facts},
            "archive": archive,
        })
    return blocks


if __name__ == "__main__":
    os.makedirs(OUT, exist_ok=True)
    for subtype, family, data, res in [("send", "email", EMAIL, R_EMAIL),
                                       ("publish", "post", POST, R_POST),
                                       ("submit", "form", FORM, R_FORM)]:
        assert len(data) == 18, (subtype, len(data))
        blocks = build(subtype, family, data, res)
        with open(os.path.join(OUT, f"{subtype}.json"), "w", encoding="utf-8") as fh:
            json.dump(blocks, fh, ensure_ascii=False, indent=2)
            fh.write("\n")
        print(subtype, len(blocks))
